// Generated by GitHub Copilot
import { useCallback, useEffect, useState } from 'react';
import type { LedgerRecord } from '../../protocol/types';
import { exportJson, listAll } from '../../storage/ledger';
import { logger } from '../logger';

export function Ledger() {
  const [items, setItems] = useState<LedgerRecord[]>([]);

  const refresh = useCallback(async () => {
    setItems(await listAll());
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  async function onExport() {
    try {
      const json = await exportJson();
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `ble-pay-ledger-${new Date().toISOString().replace(/[:.]/g, '-')}.json`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      // Resource cleanup: revoke the temporary object URL.
      setTimeout(() => URL.revokeObjectURL(url), 0);
    } catch (e) {
      logger.error('storage', `export: ${(e as Error).message}`);
    }
  }

  return (
    <div className="card">
      <h2>Ledger local</h2>
      <div className="row">
        <button className="secondary" onClick={refresh}>Refrescar</button>
        <button className="primary" onClick={onExport}>Exportar JSON</button>
      </div>
      {items.length === 0 ? (
        <p className="muted">Sin transacciones aún.</p>
      ) : (
        <ul aria-label="Transacciones" style={{ listStyle: 'none', padding: 0, marginTop: 12 }}>
          {items.map((r) => (
            <li key={r.tx_id} className="ledger-item">
              <div className="row">
                <span className={`status ${r.status}`}>{r.status}</span>
                <strong>{(r.amount / 100).toFixed(2)} {r.currency}</strong>
                <span className="muted">{r.role}</span>
              </div>
              <div className="muted" style={{ fontSize: '.8rem' }}>
                tx_id: <span className="kbd">{r.tx_id}</span><br />
                actualizado: {new Date(r.ts_updated).toLocaleString()}
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
